class TreeNode {
  constructor(
    public left: TreeNode | null,
    public right: TreeNode | null
  ) {}
}

function bottomUpTree(depth: number): TreeNode {
  return depth > 0
    ? new TreeNode(bottomUpTree(depth - 1), bottomUpTree(depth - 1))
    : new TreeNode(null, null);
}

function itemCheck(node: TreeNode): number {
  if (node.left === null) {
    return 1;
  }
  return 1 + itemCheck(node.left) + itemCheck(node.right!);
}

function main(): void {
  const maxDepth = process.argv[2] ? parseInt(process.argv[2], 10) : 21;
  const minDepth = 4;
  const stretchDepth = maxDepth + 1;

  const stretchTree = bottomUpTree(stretchDepth);
  console.log(`stretch tree of depth ${stretchDepth}\t check: ${itemCheck(stretchTree)}`);

  const longLivedTree = bottomUpTree(maxDepth);

  for (let depth = minDepth; depth <= maxDepth; depth += 2) {
    const iterations = 1 << (maxDepth - depth + minDepth);
    let check = 0;
    for (let i = 0; i < iterations; i++) {
      check += itemCheck(bottomUpTree(depth));
    }
    console.log(`${iterations}\t trees of depth ${depth}\t check: ${check}`);
  }

  console.log(`long lived tree of depth ${maxDepth}\t check: ${itemCheck(longLivedTree)}`);
}

