                        q[i] = q[j];
                        q[j] = t;
                        i++;
                        j--;
                    }
                }
                cur = qq;
                qq = q[qq];
                flips++;
            }
            if (flips > maxFlips) {
                maxFlips = flips;
            }
            checkSum += sign * flips;
