function pidigits(n: number): void {
    let q = 1n;
    let r = 0n;
    let t = 1n;
    let k = 1n;

    let i = 0;
    let line = "";
    let out = "";

    while (i < n) {
        const num = 3n * q + r;
        const d = num / t;
        const rem = num % t;

        if (rem + q < t) {
            line += d.toString();
            i++;

            if (line.length === 10) {
                out += line + "\t:" + i + "\n";
                line = "";
                if (out.length >= 65536) {
                    process.stdout.write(out);
                    out = "";
                }
            }

            r = 10n * (r - d * t);
            q = 10n * q;
        } else {
            const k2 = (k << 1n) + 1n;
            r = (r + (q << 1n)) * k2;
            t = t * k2;
            q = q * k;
            k++;
        }
    }

    if (line.length > 0) {
        out += line.padEnd(10, " ") + "\t:" + i + "\n";
    }

    if (out.length > 0) {
        process.stdout.write(out);
    }
}

