    ['V', 'B'], ['v', 'B'],
    ['H', 'D'], ['h', 'D'],
    ['D', 'H'], ['d', 'H'],
    ['B', 'V'], ['b', 'V'],
    ['N', 'N'], ['n', 'N'],
  ];
  for (const [from, to] of pairs) {
    table[from.charCodeAt(0)] = to.charCodeAt(0);
  }

  const input = fs.readFileSync(0);
  if (input.length === 0) {
    return;
  }

  function writeAll(fd: number, buf: Buffer, start: number, length: number): void {
    let written = 0;
    while (written < length) {
      written += fs.writeSync(fd, buf, start + written, length - written);
    }
  }

  let outBuf = Buffer.allocUnsafe(Math.min(input.length + 1024, 64 * 1024 * 1024));

  let pos = input.indexOf(62, 0);
  if (pos === -1) {
    return;
  }

  while (pos < input.length) {
    const headerStart = pos;
    const nextNl = input.indexOf(10, pos);
    let headerEnd: number;
    if (nextNl === -1) {
      headerEnd = input.length;
      pos = input.length;
    } else {
      headerEnd = nextNl + 1;
      pos = headerEnd;
    }
    const seqStart = headerEnd;

    let nextGt = -1;
    let searchPos = seqStart;
    while (searchPos < input.length) {
      const idx = input.indexOf(62, searchPos);
      if (idx === -1) {
        break;
      }
      if (idx === 0 || input[idx - 1] === 10 || input[idx - 1] === 13) {
        nextGt = idx;
        break;
      }
      searchPos = idx + 1;
    }

    const seqEnd = nextGt === -1 ? input.length : nextGt;
    const seqLen = seqEnd - seqStart;
    const neededOut = seqLen + Math.ceil(seqLen / 60) + 64;

    if (outBuf.length < neededOut) {
      outBuf = Buffer.allocUnsafe(neededOut);
    }

    let col = 0;
    let outPos = 0;
    for (let i = seqEnd - 1; i >= seqStart; i--) {
      const c = table[input[i]];
      if (c !== 0) {
        outBuf[outPos++] = c;
        if (++col === 60) {
          outBuf[outPos++] = 10;
          col = 0;
        }
      }
    }
    if (col > 0) {
      outBuf[outPos++] = 10;
    }

    writeAll(1, input, headerStart, headerEnd - headerStart);
    if (outPos > 0) {
      writeAll(1, outBuf, 0, outPos);
    }

    pos = seqEnd;
    if (nextGt === -1) {
      break;
    }
  }
}

