function eval_A(u: Float64Array, v: Float64Array, n: number): void {
  for (let i = 0; i < n; ++i) {
    let sum = 0.0;
    const i1 = i + 1;
    let j = 0;
    const limit = n - 3;
    for (; j < limit; j += 4) {
      const s0 = i + j;
      const s1 = s0 + 1;
      const s2 = s0 + 2;
      const s3 = s0 + 3;
      sum += u[j]     / (((s0 * (s0 + 1)) >>> 1) + i1)
           + u[j + 1] / (((s1 * (s1 + 1)) >>> 1) + i1)
           + u[j + 2] / (((s2 * (s2 + 1)) >>> 1) + i1)
           + u[j + 3] / (((s3 * (s3 + 1)) >>> 1) + i1);
    }
    for (; j < n; ++j) {
      const s = i + j;
      sum += u[j] / (((s * (s + 1)) >>> 1) + i1);
    }
    v[i] = sum;
  }
}

function eval_At(u: Float64Array, v: Float64Array, n: number): void {
  for (let i = 0; i < n; ++i) {
    let sum = 0.0;
    let j = 0;
    const limit = n - 3;
    for (; j < limit; j += 4) {
      const s0 = i + j;
      const s1 = s0 + 1;
      const s2 = s0 + 2;
      const s3 = s0 + 3;
      sum += u[j]     / (((s0 * (s0 + 1)) >>> 1) + j + 1)
           + u[j + 1] / (((s1 * (s1 + 1)) >>> 1) + j + 2)
           + u[j + 2] / (((s2 * (s2 + 1)) >>> 1) + j + 3)
           + u[j + 3] / (((s3 * (s3 + 1)) >>> 1) + j + 4);
    }
    for (; j < n; ++j) {
      const s = i + j;
      sum += u[j] / (((s * (s + 1)) >>> 1) + j + 1);
    }
    v[i] = sum;
  }
}

function eval_AtA_times_u(u: Float64Array, v: Float64Array, tmp: Float64Array, n: number): void {
  eval_A(u, tmp, n);
  eval_At(tmp, v, n);
}

function main(): void {
  const n = parseInt(process.argv[2], 10);
  const u = new Float64Array(n);
  const v = new Float64Array(n);
  const tmp = new Float64Array(n);
  u.fill(1.0);

